/bin/bash -lc "python - <<'PY'
import os,socket,urllib.request
for k,v in os.environ.items():
 if any(s in k.lower() for s in ['proxy','assembly','endpoint','base_url']):
  print(k, '[set]' if any(s in k.lower() for s in ['key','token','password']) else v)
for host in ['api.assemblyai.com','www.assemblyai.com','pypi.org']:
 try: print(host,socket.gethostbyname(host))
 except Exception as e: print(type(e).__name__)
for url in ['https://api.assemblyai.com/v2/transcript','https://www.assemblyai.com/docs/llms.txt']:
 try:
  req=urllib.request.Request(url,headers={'authorization':os.environ['ASSEMBLYAI_API_KEY']}) if 'api.assemblyai' in url else url
  r=urllib.request.urlopen(req,timeout=20);b=r.read();print(url,r.status,b[:500])
 except Exception as e: print(url,type(e).__name__,str(e))
PY"

