import urllib.request
urls=['https://assemblyai.com/docs/pre-recorded-audio/redact-pii','https://raw.githubusercontent.com/AssemblyAI/assemblyai-python-sdk/master/assemblyai/types.py','https://raw.githubusercontent.com/AssemblyAI/assemblyai-api-spec/main/openapi.yml']
